/* Example: create a composite covering index in PostgreSQL and inspect the plan */
-- Create index to support queries by user_id and status, and include non-key columns to make it covering
CREATE INDEX CONCURRENTLY ON orders(user_id, status) INCLUDE (order_id, total);

-- Check query plan and timing
EXPLAIN ANALYZE
SELECT order_id, total FROM orders
WHERE user_id = 42 AND status = 'paid'
LIMIT 50;

-- If you see Index Only Scan in the plan, the index covers the query and avoids table fetches.
